  /** Every corpus entry for a hunter in the given mode, nearest the target level first. */
  function donorsFor(hunter, mode, level) {
    const rows = CORPUS[hunter] || [];
    // EXACT MODE FIRST, THEN A DELIBERATE FALLBACK. A boss build is a deep build, so push and loot
    // donors are still useful raw material when few boss rows exist -- but they must never DISPLACE
    // a real boss donor, which is what the old boolean did by returning loot rows for a boss search.
    const near = (a, b) => a.distance - b.distance || a.level - b.level;
    const shape = (r) => ({ level: r[0], mode: r[1], code: r[2], distance: Math.abs(r[0] - level) });
    const exact = rows.filter((r) => r[1] === mode).map(shape).sort(near);
    if (mode !== 'boss' && mode !== 'bossTimeless') return exact;
    // boss and bossTimeless share their raw material: both aim at a kill, and bossTimeless differs
    // only by pinning Timeless during the search.
    const kin = rows.filter((r) => (r[1] === 'boss' || r[1] === 'bossTimeless') && r[1] !== mode)
      .map(shape).sort(near);
    const rest = rows.filter((r) => r[1] !== 'boss' && r[1] !== 'bossTimeless').map(shape).sort(near);
    return [...exact, ...kin, ...rest];
  }

  global.OptimizerCorpus = { CORPUS, donorsFor };
